package local.proskurnin.remote;
import android.content.*;import android.content.pm.*;import android.media.AudioManager;import java.util.*;import org.json.*;
final class RemoteActions {
 static final String[] DEFAULTS={"tv.okko.androidtv","ru.kinopoisk.tv","ru.ivi.client","org.smarttube.stable","mobi.zona","com.lazycatsoftware.lmd"};
 static LinkedHashMap<String,String> apps(Context c){TreeMap<String,String> sorted=new TreeMap<>(java.text.Collator.getInstance(new Locale("ru")));HashMap<String,String> names=new HashMap<>();for(String category:new String[]{Intent.CATEGORY_LEANBACK_LAUNCHER,Intent.CATEGORY_LAUNCHER})for(ResolveInfo r:c.getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(category),0)){String pkg=r.activityInfo.packageName;if(pkg.equals(c.getPackageName())||pkg.equals("local.proskurnin.homerouter")||pkg.equals("local.proskurnin.preview"))continue;names.put(pkg,r.loadLabel(c.getPackageManager()).toString());}for(String pkg:names.keySet())sorted.put(names.get(pkg)+"\u0000"+pkg,pkg);LinkedHashMap<String,String> out=new LinkedHashMap<>();for(String pkg:sorted.values())out.put(pkg,names.get(pkg));return out;}
 static JSONArray selected(Context c){try{return new JSONArray(c.getSharedPreferences("remote",0).getString("apps",new JSONArray(Arrays.asList(DEFAULTS)).toString()));}catch(Exception e){return new JSONArray(Arrays.asList(DEFAULTS));}}
 static JSONObject state(RemoteService service)throws Exception{Map<String,String> installed=apps(service);JSONArray all=new JSONArray(),quick=new JSONArray();for(String pkg:installed.keySet())all.put(new JSONObject().put("package",pkg).put("name",installed.get(pkg)));JSONArray selected=selected(service);for(int i=0;i<selected.length();i++){String pkg=selected.optString(i);if(installed.containsKey(pkg))quick.put(new JSONObject().put("package",pkg).put("name",installed.get(pkg)));}AudioManager audio=(AudioManager)service.getSystemService(Context.AUDIO_SERVICE);return new JSONObject().put("field",TextInputService.state()).put("connected",true).put("control_ready",(BridgeClient.send("PING")||TextInputService.available())).put("apps",quick).put("all_apps",all).put("volume",audio.getStreamVolume(AudioManager.STREAM_MUSIC)).put("volume_max",audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC)).put("muted",audio.isStreamMute(AudioManager.STREAM_MUSIC));}
 static synchronized boolean command(Context c,JSONObject body)throws Exception{String action=body.getString("action");if(action.equals("app")){String pkg=body.getString("package");if(!apps(c).containsKey(pkg))return false;Intent i=c.getPackageManager().getLeanbackLaunchIntentForPackage(pkg);if(i==null)i=c.getPackageManager().getLaunchIntentForPackage(pkg);if(i==null)return false;c.startActivity(i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));return true;}
  if(action.equals("sources")){Intent i=new Intent("com.android.tv.action.VIEW_INPUTS").setPackage("com.mediatek.wwtv.tvcenter");if(i.resolveActivity(c.getPackageManager())==null)i.setPackage(null);if(i.resolveActivity(c.getPackageManager())==null)return false;c.startActivity(i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));return true;}
  if(action.equals("home")){c.startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).setClassName("local.proskurnin.preview","local.proskurnin.preview.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));return true;}
  Map<String,String> commands=new HashMap<>();commands.put("up","UP");commands.put("down","DOWN");commands.put("left","LEFT");commands.put("right","RIGHT");commands.put("ok","OK");commands.put("back","BACK");commands.put("menu","MENU");commands.put("play","PLAY");commands.put("volup","VOLUP");commands.put("voldown","VOLDOWN");commands.put("mute","MUTE");String command=commands.get(action);if(command==null)return false;
  if(action.equals("volup")||action.equals("voldown")||action.equals("mute")){AudioManager audio=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);audio.adjustStreamVolume(AudioManager.STREAM_MUSIC,action.equals("volup")?AudioManager.ADJUST_RAISE:action.equals("voldown")?AudioManager.ADJUST_LOWER:AudioManager.ADJUST_TOGGLE_MUTE,AudioManager.FLAG_SHOW_UI);return true;}
  if(BridgeClient.send(command))return true;
  if(LauncherNavigation.send(c,command))return true;
  return TextInputService.navigate(command);
 }
}
